"""Named mathematical values, with legacy naming and normalization made explicit."""
from urllib.parse import quote
from common import A, DLMF
from categories import subject_category

def oeis(term):return 'https://oeis.org/search?q='+quote(term)
# name: title, definition, formula, caution, primary reference
DATA={
'PI':('Circle constant π','Ratio of a Euclidean circle’s circumference to its diameter.','C=2πr; area=πr².','Trigonometric functions use radians: a full turn is 2·PI.',DLMF+'4.3'),
'e':('Euler’s number','Base of the natural logarithm and the real exponential whose derivative is itself.','e=Σ(n=0..∞)1/n!=lim(n→∞)(1+1/n)ⁿ.','This mathematical e is not elementary electric charge; use ElementaryCharge for that physical quantity.',DLMF+'4.2'),
'EulerMascheroni':('Euler–Mascheroni constant','Constant difference between the harmonic sum and the natural logarithm in the large-n limit.','γ=lim(n→∞)[Σ(k=1..n)1/k−ln(n)].','Distinct from the gamma function gamma(x).',DLMF+'5.2'),
'GoldenRatio':('Golden ratio','Positive solution of x²=x+1; a rectangle with this aspect ratio reproduces its shape after removing a square.','φ=(1+sqrt(5))/2.','',oeis('golden ratio')),
'InverseGoldenRatio':('Reciprocal golden ratio','Positive number one less than the golden ratio.','1/φ=φ−1=(sqrt(5)−1)/2.','',oeis('inverse golden ratio')),
'SilverRatio':('Silver ratio','Positive solution of x²=2x+1; limit of successive Pell-number ratios.','δS=1+sqrt(2).','Not the legacy SilverConstant identifier, which stores the plastic number.',oeis('silver ratio')),
'AperysConstant':('Apéry’s constant','Sum of the reciprocals of positive integer cubes.','ζ(3)=Σ(n=1..∞)1/n³.','',DLMF+'25.6'),
'ConwaysConstant':('Conway look-and-say growth constant — short approximation','Asymptotic growth factor for the lengths of the usual look-and-say sequence.','length(n+1)/length(n) → λ≈1.303577269.','This identifier stores only 1.30357. ConwayConstantλ3 retains a longer approximation; neither is a runtime sequence computation.',oeis('Conway constant')),
'KhinchinsConstant':('Khinchin’s constant — short approximation','For almost every real number, the geometric mean of its regular continued-fraction partial quotients approaches this value.','(a₁a₂…aₙ)^(1/n) → K.','An almost-everywhere statement, not a property of every continued fraction. KhinchinConstantK_K0 has a longer stored approximation.',oeis('Khinchin constant')),
'ApéryConstantζ3':('Apéry’s constant ζ(3)','Sum of the reciprocals of positive integer cubes.','ζ(3)=1+1/2³+1/3³+….','Alias in meaning of AperysConstant.',DLMF+'25.6'),
'ArtinConstant':('Artin’s constant','Euler product occurring in primitive-root density problems.','A=∏(p prime)[1−1/(p(p−1))].','Interpreting this as a prime density requires the relevant Artin-conjecture hypotheses and correction factors; it is not a universal density for every base.',oeis('Artin constant')),
'BernsteinConstantβ':('Bernstein approximation constant','Asymptotic coefficient for the best uniform polynomial approximation to |x| on [−1,1].','β=lim(n→∞) n·min(deg p≤n) max(|x|≤1) ||x|−p(x)|.','This is a minimax approximation constant, not a Bernstein-polynomial coefficient.','https://oeis.org/A073001'),
'BlazysConstant':('Blažys prime continued-fraction constant','A real-number encoding of the prime sequence through a generalized continued fraction.','B=2+2/(3+3/(5+5/(7+7/(11+…)))).','This is not an independent prime-finding shortcut: the continued fraction already uses the primes. Iterating a finite-precision stored approximation cannot reliably recover arbitrarily many primes.','https://oeis.org/A233588'),
'BrunConstantforTwinPrimesB4':('Brun’s twin-prime reciprocal sum','Convergent sum of reciprocals of both members of all twin-prime pairs.','B₂=Σ(p,p+2 prime)[1/p+1/(p+2)].','The historical identifier ends in B4, but this quantity is the twin-prime B₂ constant. The stored decimal is an estimate, not an exact closed form.',oeis('Brun twin prime constant')),
'BrunConstantforPrimeCousinsB4':('Brun reciprocal sum for cousin primes','Sum of the reciprocals of both primes in every prime pair separated by four.','B₄=Σ(p,p+4 prime)[1/p+1/(p+4)].','Counts occurrences in pairs, so a prime in more than one pair contributes more than once. The stored value has limited digits.',oeis('Brun cousin primes constant')),
'BrunConstantforPrimeQuadruplesB4':('Brun reciprocal sum for prime quadruplets','Sum of reciprocals over prime quadruplets of the form (p,p+2,p+6,p+8).','Σquadruplets [1/p+1/(p+2)+1/(p+6)+1/(p+8)].','A different sum from the cousin-prime constant despite the shared B4 suffix. The stored value is an approximation.',oeis('Brun prime quadruplets constant')),
'CahenConstantC':('Cahen’s constant','Alternating reciprocal sum derived from Sylvester’s sequence of pairwise coprime integers.','C=Σ(n=0..∞)(−1)ⁿ/(sₙ−1), s₀=2, sₙ₊₁=1+∏(j=0..n)sⱼ.','The initial sequence is 2,3,7,43,1807,…; the reciprocal terms start 1−1/2+1/6−1/42+….',oeis('Cahen constant')),
'CatalanConstantC':('Catalan’s constant','Dirichlet beta function at two, an alternating reciprocal-square sum.','G=Σ(n=0..∞)(−1)ⁿ/(2n+1)².','The constant G in this formula is not the physical gravitational constant G.',DLMF+'25.11'),
'ChampernowneConstantC10':('Base-ten Champernowne constant','Decimal formed by concatenating the positive integers after the decimal point.','C₁₀=0.123456789101112131415….','Only a binary64 approximation is stored; its decimal expansion is not stored as an unlimited string.',oeis('Champernowne constant')),
'ContinuedFractionsConstant':('Reciprocal Lochs conversion factor','Typical conversion between regular continued-fraction terms and base-ten digits.','π²/[6 ln(2) ln(10)] = 1/LochConstant.','This reciprocal convention is about decimal information per continued-fraction term; LochConstant uses the opposite ratio.',oeis('1.030640834100712')),
'ConwayConstantλ3':('Conway look-and-say growth constant','Limiting length-growth factor for the standard look-and-say process, which describes runs of repeated digits.','length(n+1)/length(n) → λ≈1.303577269034296.','The longer approximation to the quantity also named ConwaysConstant.',oeis('Conway constant')),
'DelianConstant':('Delian constant','Factor by which a cube’s edge must grow to double its volume.','∛2.','A geometric scale factor, not twice the original edge length.',oeis('cube root of 2')),
'EmbreeTrefethenConstantβ':('Embree–Trefethen threshold','Threshold parameter separating typical decay from growth in a random Fibonacci-type recurrence.','bₙ₊₁=±bₙ±β·bₙ₋₁, with independent equiprobable signs.','The stored 0.70258 is a short numerical estimate. This is a stochastic asymptotic threshold, not a guarantee for every sign sequence.','https://oeis.org/A118288'),
'ErdösBorweinConstant':('Erdős–Borwein constant','Sum of reciprocals of the numbers one less than powers of two.','Σ(n=1..∞)1/(2ⁿ−1).','The series includes all n, not just n for which 2ⁿ−1 is prime.',oeis('Erdos Borwein constant')),
'FeigenbaumReductionParameterα':('Feigenbaum spatial-scaling constant','Signed spatial rescaling in the quadratic-unimodal period-doubling universality class.','α≈−2.502907875095893.','The code stores the negative rescaling convention. Many tables quote only its positive magnitude; do not confuse it with the parameter-spacing constant δ.',oeis('Feigenbaum alpha')),
'FeigenbaumBifurcationVelocityδ':('Feigenbaum parameter-scaling constant','Limit of ratios of successive parameter intervals in a quadratic-unimodal period-doubling cascade.','δ=lim(n→∞)(aₙ−aₙ₋₁)/(aₙ₊₁−aₙ).','Applies to the specified universality class, not every nonlinear system.',oeis('Feigenbaum delta')),
'FransénRobinsonConstant':('Fransén–Robinson constant','Integral of the reciprocal gamma function over the nonnegative real axis.','F=∫₀∞ 1/Γ(x) dx.','The reciprocal gamma function tends to zero at x=0, so the endpoint is interpreted continuously.',oeis('Fransen Robinson constant')),
'GaussConstantG':('Gauss arithmetic–geometric-mean constant','Reciprocal of the arithmetic–geometric mean of 1 and sqrt(2).','G=1/AGM(1,sqrt(2)).','Related to the lemniscatic complete elliptic integral, not the gravitational G.',oeis('Gauss constant arithmetic geometric')),
'GaussKuzminWirsingConstantλ1':('Gauss–Kuzmin–Wirsing constant','Magnitude of the subdominant transfer-operator eigenvalue governing convergence in continued-fraction statistics.','λ≈0.3036630028987327.','It is a convergence-rate constant, not the Khinchin geometric mean or the Lévy denominator-growth constant.',oeis('Gauss Kuzmin Wirsing constant')),
'GelfondConstant':('Gelfond’s constant','Exponential of π, arising naturally in complex exponentiation.','exp(π).','',oeis('Gelfond constant')),
'GelfondSchneiderConstant':('Gelfond–Schneider constant','Two raised to the irrational algebraic power sqrt(2).','2^sqrt(2).','Distinct from exp(PI).',oeis('Gelfond Schneider constant')),
'GerverMovingSofaConstant':('Area of Gerver’s moving sofa','Area of Gerver’s unit-corridor sofa construction in the right-angle moving-sofa problem.','Area≈2.21953166887197 for corridor width 1.','For corridor width w, area scales by w². This stored construction value is not an algorithm for motion planning.',oeis('Gerver sofa constant')),
'HammersleyUpperBoundOnGerverConstant':('Hammersley sofa construction area — legacy name','Area of Hammersley’s unit-corridor moving-sofa construction.','π/2+2/π.','The identifier is misleading: this feasible construction supplies a LOWER bound on the maximum possible sofa area, not an upper bound on Gerver’s construction.',oeis('Hammersley sofa pi/2')),
'GibbsConstantG':('Sine integral at π','Integral underlying the overshoot of Fourier partial sums at a jump.','Si(π)=∫₀π sin(t)/t dt.','This number ≈1.851937 is not the usual ≈0.08949 fractional Gibbs overshoot.',DLMF+'6.2'),
'WilbrahamGibbsConstantG':('Gibbs overshoot factor — 2Si(π)/π convention','Normalized sine-integral factor for the first overshoot near a Fourier-series jump.','2Si(π)/π≈1.17897974447.','The usual fractional excess relative to the jump is (this value−1)/2≈0.0894898722, not this stored factor itself.',DLMF+'6.2'),
'GlaisherKinkelinConstantA':('Glaisher–Kinkelin constant','Constant associated with hyperfactorials and the derivative of the zeta function at −1.','A=exp(1/12−ζ′(−1)).','',DLMF+'25.6'),
'GolombDickmanConstantλ':('Golomb–Dickman constant','Asymptotic expected fraction of elements in the longest cycle of a uniformly random permutation.','E(longest cycle of n objects)/n → λ.','Also occurs in the distribution of the largest prime factor; these are limiting statistics.',oeis('Golomb Dickman constant')),
'GompertzConstantG':('Euler–Gompertz constant','Integral related to the exponential integral at one.','G=∫₀∞ exp(−t)/(1+t) dt=e·E₁(1).','Do not confuse this mathematical constant with the gravitational constant G.',DLMF+'6.2'),
'GrossmannConstant':('Grossman recurrence constant','Special initial value selecting the convergent orbit of x₀=1, x₁=c, xₙ₊₂=xₙ/(1+xₙ₊₁).','c≈0.73733830336929.','The identifier uses the legacy double-n spelling. Sensitive recurrence iteration is not reliably determined by unlimited use of this rounded value.',oeis('Grossman constant')),
'KhinchinConstantK_K0':('Khinchin’s constant','Almost-everywhere geometric mean of regular continued-fraction partial quotients.','K=∏(r=1..∞)[1+1/(r(r+2))]^(log₂ r).','Not every real number has this mean; simple periodic continued fractions are notable exceptions.',oeis('Khinchin constant')),
'KhinchinLévyConstantγ':('Exponential Lévy denominator-growth constant','Typical exponential growth factor of regular continued-fraction convergent denominators.','lim qₙ^(1/n)=exp(π²/(12 ln2)).','This is the exponential of LévyConstantγ, not its logarithmic version.',oeis('Khinchin Levy constant')),
'KnuthRandomgeneratorsConstant':('Knuth random-generator algebraic constant','Algebraic constant appearing in analysis of random-number generators.','(1−1/sqrt(3))/2.','A fixed mathematical value, not a random-number generator, seed or security parameter.',oeis('0.211324865405187')),
'KolakoskiConstantγ':('Kolakoski binary-encoding constant','Binary real formed from the self-run-length-describing Kolakoski sequence 1,2,2,1,1,2,…, after omitting the initial 1 and mapping 1→0, 2→1.','0.110010110… in base 2.','This number is not the conjectured frequency of the symbol 1.','https://oeis.org/A118270'),
'LandauRamanujanConstant':('Landau–Ramanujan constant','Coefficient in the count of positive integers expressible as a sum of two integer squares.','Count≤x ~ K·x/sqrt(ln x).','Counts represented integers once, not their number of different representations.',oeis('Landau Ramanujan constant')),
'LaplaceLimitConstantλ':('Laplace limit for Kepler-series convergence','Eccentricity threshold for convergence of the classical eccentricity power series used in Kepler’s equation.','λ·exp(sqrt(1+λ²))/(1+sqrt(1+λ²))=1; λ>0.','This concerns that series, not the existence of a solution to Kepler’s equation.',oeis('Laplace limit constant')),
'LemniscateConstantL':('Lemniscate constant','Twice the basic lemniscatic quarter-period integral.','L=2∫₀¹ dt/sqrt(1−t⁴)=Γ(1/4)²/(2sqrt(2π)).','The normalization is L≈2.62205755; FirstLemniscateConstantLA stores half this value.',DLMF+'19.8'),
'FirstLemniscateConstantLA':('First lemniscatic integral','Integral of the reciprocal square root of 1−t⁴ from zero to one.','LA=∫₀¹ dt/sqrt(1−t⁴)=L/2.','The integrable endpoint singularity is part of the definition.',DLMF+'19.8'),
'SecondLemniscateConstantLB':('Second lemniscatic integral','Second basic definite integral associated with the lemniscate.','LB=∫₀¹ t² dt/sqrt(1−t⁴)=π/(4LA).','The stored normalization is about 0.599070117, not L or LA.',DLMF+'19.8'),
'LévyConstantγ':('Logarithmic Lévy constant','Almost-everywhere limiting logarithmic growth rate of continued-fraction convergent denominators qₙ.','lim ln(qₙ)/n=π²/(12 ln2).','Its exponential is KhinchinLévyConstantγ.',oeis('Levy constant')),
'LiouvilleConstant':('Liouville’s constant','Decimal with ones at factorial-numbered positions and zeros elsewhere.','L=Σ(n=1..∞)10^(−n!).','The stored binary64 value cannot retain the isolated digits arbitrarily far into the decimal expansion.',oeis('Liouville constant')),
'LochConstant':('Lochs’ constant','Typical number of regular continued-fraction terms determined per base-ten digit.','6 ln2 ln10/π².','The identifier omits the final s in Lochs. ContinuedFractionsConstant is its reciprocal.',oeis('Lochs constant')),
'MadelungConstantM3':('NaCl-lattice Madelung sum — signed convention','Electrostatic lattice sum for alternating unit charges on a simple cubic array, with the reference ion at the origin.','Σ′(i,j,k) (−1)^(i+j+k)/sqrt(i²+j²+k²), under the electrostatic/Ewald summation convention.','The stored value is negative. Many chemistry tables quote the positive magnitude ≈1.74756. The three-dimensional series is not absolutely convergent; arbitrary summation orders are unsafe.',oeis('Madelung constant NaCl')),
'MeisselMertensConstantB1':('Meissel–Mertens prime constant','Constant term in the asymptotic sum of reciprocals of primes.','B₁=lim(x→∞)[Σ(p≤x prime)1/p−ln ln x].','Not the Euler–Mascheroni harmonic-sum constant.',oeis('Meissel Mertens constant')),
'MillsConstantA':('Mills’ prime-representing constant','Smallest constant in the classical construction where floor(A^(3ⁿ)) is prime for each positive integer n.','floor(A^(3ⁿ)).','A finite binary64 approximation does not reliably generate large primes. Stored digits refer to the conventional least-prime construction and its computation assumptions.',oeis('Mills constant')),
'MKBconstant':('MKB oscillatory-integral constant','Absolute value of a particular oscillatory integral limit, related to the MRB sum.','|lim(N→∞)∫₁^(2N) exp(iπx)·x^(1/x) dx|.','The upper limits are the even integers 2N; replacing this by an arbitrary improper-integral limit changes the convergence question.','https://oeis.org/A157852'),
'MRBconstant':('MRB constant','Even-partial-sum limit of an alternating sequence of n-th roots.','lim(N→∞)Σ(n=1..2N)(−1)ⁿ n^(1/n).','The even cutoff is essential because the term magnitudes approach 1.','https://oeis.org/A037077'),
'OmegaConstantW1':('Omega constant','Positive real solution of w·exp(w)=1.','Ω=W₀(1)=exp(−Ω).','',DLMF+'4.13'),
'OtterConstantα':('Otter tree-growth constant','Exponential growth rate of the number of unlabeled trees.','α≈2.95576528565.','The polynomial factor and leading coefficient differ for rooted and unrooted trees.',oeis('Otter constant')),
'OtterAsymptoticConstantβuForUnrootedTrees':('Otter coefficient for unrooted trees','Leading coefficient in the asymptotic count of unlabeled unrooted trees with n vertices.','tₙ ~ βu·αⁿ·n^(−5/2).','α is OtterConstantα. The coefficient’s finite stored digits limit its precision.',oeis('Otter unrooted trees constant')),
'OtterAsymptoticConstantβrForRootedTrees':('Otter coefficient for rooted trees','Leading coefficient in the asymptotic count of unlabeled rooted trees with n vertices.','rₙ ~ βr·αⁿ·n^(−3/2).','α is OtterConstantα; do not use the unrooted n^(−5/2) exponent here.',oeis('Otter rooted trees constant')),
'PlasticNumberρ':('Plastic number','Unique real root greater than one of a cubic; limiting ratio for Padovan-type recurrences.','ρ³=ρ+1.','',oeis('plastic constant')),
'SilverConstant':('Plastic number — legacy silver-constant name','Legacy alias in meaning for the unique positive real solution of x³=x+1.','ρ≈1.324717957244746.','This does NOT equal the usual silver ratio 1+sqrt(2); use SilverRatio for that value.',oeis('plastic constant')),
'PogsonRatio':('Pogson brightness ratio','Flux ratio corresponding to one unit of astronomical magnitude difference.','100^(1/5)=10^0.4.','Five magnitudes correspond to a factor 100 in flux. Smaller magnitudes denote greater brightness.',oeis('Pogson ratio')),
'PolyaRandomwalkConstantp3':('Three-dimensional random-walk return probability','Probability that a simple symmetric walk on the cubic integer lattice ever returns to its starting point after departure.','preturn≈0.340537329551.','Each step chooses one of six nearest neighbours equally. This is an eventual-return probability, not a probability at a specified time.',oeis('Polya random walk constant')),
'PrévostConstant':('Reciprocal Fibonacci constant','Sum of reciprocals of the positive-index Fibonacci numbers, with F₁=F₂=1.','Σ(n=1..∞)1/Fₙ.','The two initial ones both contribute.',oeis('reciprocal Fibonacci constant')),
'ReciprocalEvenFibonacciConstant':('Even-index reciprocal Fibonacci sum','Sum of reciprocals of Fibonacci numbers whose INDEX is even.','Σ(n=1..∞)1/F₂ₙ.','“Even” refers to the index, not whether the Fibonacci value is even.',oeis('reciprocal even Fibonacci constant')),
'ReciprocalOddFibonacciConstant':('Odd-index reciprocal Fibonacci sum','Sum of reciprocals of Fibonacci numbers whose INDEX is odd, including F₁=1.','Σ(n=1..∞)1/F₂ₙ₋₁.','Together with the even-index sum, this gives PrévostConstant.',oeis('reciprocal odd Fibonacci constant')),
'RényiParkingConstantm':('Rényi random-parking constant','Limiting mean covered fraction when unit intervals are sequentially placed uniformly at random on a long line without overlap until no more fit.','Covered fraction → about 0.7475979203.','Random sequential placement differs from optimal packing, whose one-dimensional covered fraction can be 1.',oeis('Renyi parking constant')),
'SalemNumberσ1':('Lehmer’s Salem number','Real root greater than one of Lehmer’s degree-ten reciprocal polynomial.','x¹⁰+x⁹−x⁷−x⁶−x⁵−x⁴−x³+x+1=0.','An important Salem-number example. The identifier is not proof that no smaller Salem number can exist.',oeis('Lehmer Salem number')),
'SierpinskiConstantK':('Sierpiński sum-of-two-squares constant','Constant term associated with weighted counts of representations of integers as two squares.','K=π[2γ+2ln2+3lnπ−4lnΓ(1/4)].','This is not the Sierpiński triangle dimension or a Sierpiński integer.','https://oeis.org/A062089'),
'SoldnerConstantμ':('Ramanujan–Soldner constant','Positive zero above one of the principal-value logarithmic integral.','li(μ)=0, where li(x)=PV∫₀ˣ dt/ln t.','The li convention includes the interval from zero; an offset integral starting at 2 has a different zero.',oeis('Ramanujan Soldner constant')),
'SomosQuadraticRecurrenceConstant':('Somos quadratic-recurrence constant','Weighted infinite product controlling a quadratic recurrence’s growth.','σ=∏(n=1..∞)n^(1/2ⁿ)=exp(Σ ln(n)/2ⁿ).','Not the Somos integer sequences with bilinear recurrences.',oeis('Somos quadratic recurrence constant')),
'ShallWilsonOrTwinPrimesConstantC2':('Twin-prime product constant','Euler product appearing in the Hardy–Littlewood twin-prime conjecture.','C₂=∏(p>2 prime)p(p−1)⁻²(p−2).','Distinct from Brun’s convergent sum of reciprocal twin primes. The conjectural counting coefficient is 2C₂.',oeis('twin prime constant')),
'TheodorusConstant':('Theodorus’ constant','Square root of three, equal to the space diagonal of a unit cube.','sqrt(3).','',oeis('square root of 3')),
'ViswanathConstant':('Viswanath random-Fibonacci growth constant','Almost-sure exponential growth rate of the absolute value in the equal-probability random Fibonacci recurrence.','xₙ₊₁=xₙ±xₙ₋₁; |xₙ|^(1/n)→v for typical sign sequences.','A probabilistic asymptotic statement, not an identity for each finite sequence.',oeis('Viswanath constant')),
'MagicAngle':('Magic angle','Angle where the second Legendre polynomial of its cosine vanishes.','θ=arccos(1/sqrt(3)); 3cos²θ−1=0.','Stored in radians (about 54.7356 degrees), useful in orientational averaging and NMR.',DLMF+'18.3'),
'ComplementaryMagicAngle':('Complement of the magic angle','Angle that adds to the magic angle to make a right angle.','PI/2−MagicAngle.','Stored in radians (about 35.2644 degrees).',DLMF+'18.3'),
'TetrahedralAngle':('Tetrahedral bond angle','Angle between rays from a regular tetrahedron’s centre to two vertices.','arccos(−1/3).','Stored in radians (about 109.4712 degrees).',oeis('tetrahedral angle')),
'ComplementaryTetrahedralAngle':('Supplement of the tetrahedral angle — legacy name','Angle adding to the tetrahedral angle to make a straight angle.','PI−TetrahedralAngle=arccos(1/3).','The identifier says complementary, but this is the SUPPLEMENT (about 70.5288 degrees), stored in radians.',oeis('tetrahedral angle')),
'GravitoidConstant':('Gravitoid width-to-depth ratio','Geometric ratio in the homogeneous axisymmetric shape maximizing surface gravitational acceleration for fixed mass and density.','(64/27)^(1/4).','A dimensionless shape coefficient, not Newton’s gravitational constant.','https://oeis.org/A208745'),
'MinimumAreaOfAConstantWidthFigure':('Minimum area for a unit-width convex plane figure','Area of a width-one Reuleaux triangle, the minimum among convex plane bodies of constant width one.','(PI−sqrt(3))/2.','For width w, multiply by w². This is not the area of a disk of diameter one.',oeis('Reuleaux triangle area')),
'MoserWormConstant':('Historical Moser-worm covering value','A stored area estimate associated with the problem of a convex planar cover accommodating every curve of length one.','Stored candidate area≈0.23223921.','Treat this legacy value as a historical covering estimate, not a certified exact minimum or a current best bound. Rescaling curve length by L scales cover area by L².',oeis('Moser worm 0.23223921')),
'SquareDrillConstant':('Reuleaux square-drilling area ratio','Fraction of the square area reached by the idealized Reuleaux-triangle square-drilling construction.','2sqrt(3)+PI/6−3.','About 98.77 percent; it is not complete coverage of a mathematically sharp-cornered square.',oeis('0.9877003907360534')),
'UniversalParabolicConstant':('Universal parabolic constant','Arc-length ratio for a parabola: the arc cut off by its latus rectum divided by its semilatus rectum.','sqrt(2)+ln(1+sqrt(2)).','A dimensionless ratio independent of the parabola’s scale.',oeis('universal parabolic constant')),
'PowerTowerOfI':('Principal infinite power tower of i','Attracting fixed point of repeatedly applying z↦iᶻ with the principal logarithm convention.','z=iᶻ=exp(iπz/2); z≈0.4382829367+0.3605924719i.','Branch conventions matter; a finite stored complex approximation is returned, not an iteration at runtime.',DLMF+'4.13'),
'i':('Imaginary unit','The complex number whose real part is zero and imaginary part is one.','i²=−1.','System.Numerics.Complex value, distinct from a user’s local loop variable with the same name.','https://learn.microsoft.com/dotnet/api/system.numerics.complex.imaginaryone'),
'NaN':('Not-a-number sentinel','IEEE floating-point marker for an undefined or unrepresentable numerical result.','NaN is not equal to itself under ordinary floating-point equality.','It is not a real mathematical constant or a variable. Arithmetic usually propagates NaN; test with an appropriate IsNaN predicate, not equality.','https://learn.microsoft.com/dotnet/api/system.double.nan'),
'Infinity':('Positive floating-point infinity','IEEE positive-infinity value used for overflow and certain singular results.','+∞.','Not an arbitrarily large finite real number. Expressions such as Infinity−Infinity yield NaN; use −Infinity for the negative value.','https://learn.microsoft.com/dotnet/api/system.double.positiveinfinity'),
}

def describe(item, values):
    name=item['signature']; title,definition,formula,note,url=DATA[name]
    value=values.get(name,'0 + 1i' if name=='i' else None)
    if value is None:raise KeyError(name)
    units='radians' if 'Angle' in name else 'dimensionless'
    representation='Stored application value: '+value+'. '+units.capitalize()+'.'
    if name not in ('NaN','Infinity','i'):
        note+=' This is the finite stored binary64 approximation, not an arbitrary-precision evaluation of the defining limit, series or construction.'
    return A(title,definition,formula,representation,note.strip(),url=url,
             category=subject_category('MathematicalConstants', name))
